<template><div class="gva-form-box"><div class="head"><div><h2>导入任务</h2><p>查看论坛帖子导入队列、重试次数和质量结果。</p></div></div><div class="toolbar"><el-input v-model="keyword" clearable placeholder="标题或帖子 ID" @keyup.enter="load"/><el-input v-model="sourceId" clearable placeholder="来源 ID" inputmode="numeric"/><el-select v-model="status" clearable placeholder="状态" @change="load"><el-option label="待处理" value="pending"/><el-option label="运行中" value="running"/><el-option label="成功" value="succeeded"/><el-option label="失败" value="failed"/><el-option label="已取消" value="cancelled"/></el-select><el-button :icon="Search" @click="load">查询</el-button></div><el-table v-loading="loading" :data="rows" border><el-table-column label="任务 ID" width="170"><template #default="{row}"><code>{{row.id}}</code></template></el-table-column><el-table-column prop="candidateId" label="候选 ID" width="170"><template #default="{row}"><code>{{row.candidateId}}</code></template></el-table-column><el-table-column label="标题" min-width="240"><template #default="{row}">{{row.displayTitle||row.threadTitle}}</template></el-table-column><el-table-column prop="sourceName" label="来源" width="130"/><el-table-column prop="status" label="状态" width="100"/><el-table-column label="进度" width="120"><template #default="{row}">{{row.importedChapterCount}} / {{row.totalChapterCount}}</template></el-table-column><el-table-column label="尝试" width="80"><template #default="{row}">{{row.attemptCount}} / {{row.maxAttempts}}</template></el-table-column><el-table-column prop="createdAt" label="创建时间" width="180"/><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="detail(row)">详情</el-button><el-button link type="warning" :disabled="!['failed','cancelled'].includes(row.status)" @click="retry(row)">重试</el-button><el-button link type="danger" :disabled="!['pending','running'].includes(row.status)" @click="cancel(row)">取消</el-button></template></el-table-column></el-table><div class="pager"><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next" @size-change="load" @current-change="load"/></div><el-dialog v-model="dialog" title="导入任务详情" width="620px"><el-descriptions v-if="current" :column="1" border><el-descriptions-item label="任务 ID"><code>{{current.id}}</code></el-descriptions-item><el-descriptions-item label="候选 / 来源">{{current.candidateId}} / {{current.sourceName}}</el-descriptions-item><el-descriptions-item label="标题">{{current.displayTitle||current.threadTitle}}</el-descriptions-item><el-descriptions-item label="导入模式">{{current.importMode}} / {{current.mergeStrategy}}</el-descriptions-item><el-descriptions-item label="状态">{{current.status}}</el-descriptions-item><el-descriptions-item label="质量">{{current.qualityStatus}} {{current.qualitySummary}}</el-descriptions-item><el-descriptions-item label="失败原因">{{current.failReason||'-'}}</el-descriptions-item></el-descriptions></el-dialog></div></template>
<script setup>
import { ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Search } from '@element-plus/icons-vue'
import { listCrawlImportTasks, getCrawlImportTask, retryCrawlImportTask, cancelCrawlImportTask } from '@/api/novel/crawlImportTasks'
defineOptions({ name: 'NovelCrawlImportTasks' })
const rows=ref([]),total=ref(0),page=ref(1),pageSize=ref(20),keyword=ref(''),sourceId=ref(''),status=ref(''),loading=ref(false),dialog=ref(false),current=ref(null)
const load=async()=>{loading.value=true;try{const r=await listCrawlImportTasks({keyword:keyword.value,sourceId:sourceId.value,status:status.value,page:page.value,pageSize:pageSize.value});rows.value=r.data?.list||[];total.value=r.data?.total||0}finally{loading.value=false}}
const detail=async(row)=>{const r=await getCrawlImportTask(row.id);current.value=r.data;dialog.value=true}
const retry=async(row)=>{await retryCrawlImportTask(row.id);ElMessage.success('已重新排队');load()}
const cancel=async(row)=>{try{await ElMessageBox.confirm('确定取消该导入任务吗？','取消确认',{type:'warning'});await cancelCrawlImportTask(row.id);ElMessage.success('已取消');load()}catch{ElMessage.info('已取消操作')}}
load()
</script>
<style scoped>.gva-form-box{padding:20px}.head{margin-bottom:18px}.head h2{margin:0}.head p{color:var(--el-text-color-secondary)}.toolbar{display:flex;gap:10px;margin-bottom:14px}.toolbar .el-input{max-width:240px}.pager{display:flex;justify-content:flex-end;margin-top:16px}code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace}</style>
